// Verify dafny/AuctionCore.dfy, compile it to JS, and wrap the CommonJS output as an ES module at
// packages/commerce/src/generated/auction-core.js. Needs `dafny` (4.11) on PATH.
// Run: bun run build:dafny. The generated file is committed; tests/unit/dafny-fresh.test.ts fails
// if it no longer matches the .dfy (when dafny is installed).
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, writeFileSync, rmSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { homedir } from 'node:os';

// Run from the repo root (`bun run build:dafny`, or vitest), so the root is where we are.
const root = process.cwd();

/** One entry per proved module: its source, the module name inside it, and where its JS goes. */
export const MODULES = [
	{
		source: 'dafny/AuctionCore.dfy',
		module: 'AuctionCore',
		out: 'packages/commerce/src/generated/auction-core.js'
	}
];

/** @param {{ source: string, module: string, out: string }} entry */
export function compile({ source, module }) {
	const work = mkdtempSync(join(process.env.TMPDIR || join(homedir(), '.tmp'), 'dafny-'));
	try {
		execFileSync(
			'dafny',
			['build', '--target:js', join(root, source), '--output', join(work, 'out')],
			{
				stdio: ['ignore', 'inherit', 'inherit'],
				env: { ...process.env, NODE_PATH: join(root, 'node_modules') }
			}
		);
		const js = readFileSync(join(work, 'out.js'), 'utf8')
			.replace(
				"const BigNumber = require('bignumber.js');",
				"import BigNumber from 'bignumber.js';"
			)
			.replace(/\nlet _module = \(function\(\) \{[\s\S]*$/, '\n');
		if (js.includes('require(')) throw new Error('unexpected require() left in Dafny output');
		return `// @ts-nocheck\n// GENERATED by scripts/build-dafny.mjs from ${source}. Do not edit.\n${js}\nexport { _dafny, ${module} };\n`;
	} finally {
		rmSync(work, { recursive: true, force: true });
	}
}

if (process.argv[1] && process.argv[1].endsWith('build-dafny.mjs')) {
	for (const entry of MODULES) {
		const target = join(root, entry.out);
		mkdirSync(join(target, '..'), { recursive: true });
		writeFileSync(target, compile(entry));
		console.log(`wrote ${entry.out}`);
	}
}
